INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('231448c79db43d727b3a','AMEDEX 2025 Orthopaedic  (2).pdf','115','Orthopaedics/Rheumatology','A 47-year-old woman presents to your practice
complaining of progressive right elbow pain for
the past two months. She is an office secretary
and her job entails lots of computer keyboard
and mouse use. The pain increases throughout
the day as she performs her tasks. Recently,
the pain is also brought up by gripping and
sometimes persists at night. On examination,
there is no deformity, redness, or warmth of the
right elbow, and the range of motion is normal.
However, palpation elicits tenderness
approximately 2 cm below the right lateral
epicondyle. Fingers and wrist have a normal
range of motion but passive terminal flexion of
the wrist and resisted extension of the wrist and
middle finger reproduce the pain. Which one of
the following is the most likely cause of this
presentation?','{"A":"Olecranon bursitis.","B":"RB Lateral epicondylitis.","C":"Medial epicondylitis.","D":"Rupture of the wrist extensor","E":"tendons."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-b99d2d60f689","duplicate_sources":[{"record_id":"231448c79db43d727b3a","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_page":115,"source_qid":null}],"parser_version":"2.8.2-residual-resolver-page-checkpoint-local-render-2026-09-23","parser_mode":"v28_selective_ocr_base_parser","text_method":"v28_selective_ocr","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','low','{"record_id":"231448c79db43d727b3a","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_year":2025,"source_page":115,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"A 47-year-old woman presents to your practice\ncomplaining of progressive right elbow pain for\nthe past two months. She is an office secretary\nand her job entails lots of computer keyboard\nand mouse use. The pain increases throughout\nthe day as she performs her tasks. Recently,\nthe pain is also brought up by gripping and\nsometimes persists at night. On examination,\nthere is no deformity, redness, or warmth of the\nright elbow, and the range of motion is normal.\nHowever, palpation elicits tenderness\napproximately 2 cm below the right lateral\nepicondyle. Fingers and wrist have a normal\nrange of motion but passive terminal flexion of\nthe wrist and resisted extension of the wrist and\nmiddle finger reproduce the pain. Which one of\nthe following is the most likely cause of this\npresentation?","options":{"A":"Olecranon bursitis.","B":"RB Lateral epicondylitis.","C":"Medial epic