INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7127b75f5d9e7c3361d6','AMEDEX 2025 Orthopaedic  (2).pdf','121','Orthopaedics/Rheumatology','Janet is a 43-year-old IT worker, who has
presented to you with a complaint of pain in the
right elbow. She describes that the pain
increases throughout the day as she does her
job which includes lots of typing with a computer
keyboard and the use of a computer mouse. On
examinations, the elbow looks normal with a
preserved range of motion, but slight pain at the
extreme of pronation. Tenderness is elicited
over the lateral epicondyle of the right humerus
when palpated deeply. The pain is reproduced
on the resisted extension of the wrist while her
forearm is fully extended. The arm is otherwise
normal. Which one of the following would be the
best treatment option for Janet at this stage?','{"A":"Immobilization of the elbow.","B":"Corticosteroid injection.","C":"Encircling support strap for the right\nforearm.","D":"Oral NSAIDs.","E":"Topical NSAIDs."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-6433c369e18c","duplicate_sources":[{"record_id":"7127b75f5d9e7c3361d6","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_page":121,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7127b75f5d9e7c3361d6","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_year":2025,"source_page":121,"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"Janet is a 43-year-old IT worker, who has\npresented to you with a complaint of pain in the\nright elbow. She describes that the pain\nincreases throughout the day as she does her\njob which includes lots of typing with a computer\nkeyboard and the use of a computer mouse. On\nexaminations, the elbow looks normal with a\npreserved range of motion, but slight pain at the\nextreme of pronation. Tenderness is elicited\nover the lateral epicondyle of the right humerus\nwhen palpated deeply. The pain is reproduced\non the resisted extension of the wrist while her\nforearm is fully extended. The arm is otherwise\nnormal. Which one of the following would be the\nbest treatment option for Janet at this stage?","options":{"A":"Immobilization of the elbow.","B":"Corticosteroid injection.","C":"Encircling support strap for the right\nforearm.","D":"Or