INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8db1d252f807316c4ab9','AMEDEX 2025 Orthopaedic  (2).pdf','146','Orthopaedics/Rheumatology','Michael is a 66-year-old patient of yours, who
has osteoarthritis of the left knee. Six months
ago and after non-pharmacological measures
and paracetamol on an as-needed basis failed
to relieve the pain, you started him on regular
full-dose paracetamol. Today he is at your
practice with the complaint that he is still
suffering from severe knee pain despite taking
paracetamol. He is diabetic and has ischemic
heart disease and peptic ulcer disease. Which
one of the following is the most appropriate
option to add to paracetamol at this stage?','{"A":"A Celecoxib.","B":"B Tramadol.","C":"( )c | Codeine.","D":"D Slow-release morphine\npreparations.","E":"E Diclofenac."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","supporting_pages":[146,147],"source_qid":null,"duplicate_group_id":"exact-14ad6f31fa10","duplicate_sources":[{"record_id":"8db1d252f807316c4ab9","record_type":"text_mcq","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_page":146,"source_qid":null},{"record_id":"1ad2f117bbec22fd874a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1135,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8db1d252f807316c4ab9","source_file":"AMEDEX 2025 Orthopaedic  (2).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Orthopaedic  (2).pdf","source_year":2025,"source_page":146,"supporting_pages":[146,147],"source_qid":null,"domain_hint":"Orthopaedics/Rheumatology","stem":"Michael is a 66-year-old patient of yours, who\nhas osteoarthritis of the left knee. Six months\nago and after non-pharmacological measures\nand paracetamol on an as-needed basis failed\nto relieve the pain, you started him on regular\nfull-dose paracetamol. Today he is at your\npractice with the complaint that he is still\nsuffering from severe knee pain despite taking\nparacetamol. He is diabetic and has ischemic\nheart disease and peptic ulcer disease. Which\none of the following is the most appropriate\noption to add to paracetamol at this stage?","options":{"A":"A Celecoxib.","B":"B Tramadol.","C":"( )c | Codeine.","D":"D Slow-releas