INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('5bf715babe043665e697','AMEDEX 2025 PAEDIATRIC (1).pdf','1','Paediatrics','A 6-year-old girl is brought to your practice by
her parents with a 4-day history of bilateral
knee and ankle pain. On examination, she
has a temperature of 37.6 C. Her joints are
tender but there is no swelling, inflammations
or synovial thickening. The full range of
motion of the joints is preserved. Palpable
