INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7d2e894901c9431fe15a','AMEDEX 2025 PAEDIATRIC (1).pdf','56','Paediatrics','A 10-year-old boy is referred to your clinic from
his school to assess probable hearing deficit
because he has difficulty hearing, resulting in
dropped school performance. You carry out a
Rinne test that is positive in both ears. A Weber
test shows no lateralisation; however, he has a
symmetrical decreased hearing threshold.
