INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('f91ebebbc74faad7ddf6','AMEDEX 2025 PAEDIATRIC (1).pdf','171','Paediatrics','A 4-year-old child is brought to your practice
with complaint of intermittent right upper
quadrant (RUQ) and right flank pain for
2 years. These painful episodes frequently
have been associated with vomiting and
lasted for 3 hours. He has been well in
between the episodes. This time, the pain has
lasted for 12 hours. On examination, a mass
is palpated in the RUQ. The mass is tender to
palpation. Which one of the following is the
