INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('49cc1fd10734a9643f6c','AMEDEX 2025 PAEDIATRIC (3).pdf','63','Paediatrics','Option D Is correct
Childhood cervical masses are common in general
practice. They often cause significant parental
anxiety and a potential diagnostic dilemma. While
these masses are commonly benign, other
possibilities should be considered. A good
knowledge of relevant anatomy and a thorough
and systematic history, examination, and
investigations are crucial to ensure an appropriate
and efficient approach.
Cervical masses in children are divided into the
following broad categories:
1. Congenital
2. Inflammatory/ infective
3. Neoplastic
While most childhood neck lumps seen in general
practice occur due to an inflammatory or infectious
process, other possibilities, such as persistent
congenital abnormalities and red flags of
neoplastic diseases, must always be considered.
In history, three main components should
always be covered:
1. Timeline (since when and for how long has the
mass been present?','{"A":"Time course (how fast is the mass growing/has","B":"grown?)","C":"Associated features/ red flags.","D":"Cervical masses in the neonatal period and ea","E":"infancy are oftan TATTESTtal =a oe [ora"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-4b55f08b7db8","duplicate_sources":[{"record_id":"49cc1fd10734a9643f6c","record_type":"text_mcq","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_page":63,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"49cc1fd10734a9643f6c","source_file":"AMEDEX 2025 PAEDIATRIC (3).pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 PAEDIATRIC (3).pdf","source_year":2025,"source_page":63,"source_qid":null,"domain_hint":"Paediatrics","stem":"Option D Is correct\nChildhood cervical masses are common in general\npractice. They often cause significant parental\nanxiety and a potential diagnostic dilemma. While\nthese masses are commonly benign, other\npossibilities should be considered. A good\nknowledge of relevant anatomy and a thorough\nand systematic history, examination, and\ninvestigations are crucial to ensure an appropriate\nand efficient approach.\nCervical masses in children are divided into the\nfollowing broad categories:\n1. Congenital\n2. Inflammatory/ infective\n3. Neoplastic\nWhile most childhood neck lumps seen in general\npractice occur due to an inflammatory or infectious\nprocess, other possibilities, such as persistent\ncongenital abnormalities and red flags of\nneoplastic diseases, must always be considered.\nIn history, three main components should\nalways be covered:\n1. Tim