INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('91a872aba76d2903c0ef','AMEDEX 2025 Pharmacology 1-33.pdf','3','Pharmacology','Option A Is correct
Tirofiban and abciximab are glycoprotein IIb/Illa
inhibitors. Their mechanism of action is preventing
fibrin from binding to platelets by occupying the
glycoprotein Illa/IIb receptors. They may be
indicated in management of unstable angina, or
NSTEMI, particularly if early cardiac catheterization
is planned.
Contraindications to their use include:
e History of stroke within 30 days or any
history of hemorrhagic stroke
e Known history of intracranial disease (e.g.,
neoplasm, arteriovenous malformation,
aneurysm)
e Active or recent (within the previous 30
days) clinically relevant bleeding (e.g.,
gastrointestinal bleeding)
e Malignant hypertension
e Trauma or major surgical intervention within
the past 6 weeks
e Thrombocytopenia (platelet count
<100,000/mm?','{"A":"disorders of platelet\nfunction","B":"Clotting disturbances (e.g. prothrombin time\n>1.3 times normal or INR >1.5)","C":"Severe liver failure","D":"Tirofiban is not recommended itn the followin","E":"Situations:"}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-82332090a0f4","duplicate_sources":[{"record_id":"91a872aba76d2903c0ef","record_type":"text_mcq","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_page":3,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"five_block_inferred","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"91a872aba76d2903c0ef","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_year":2025,"source_page":3,"source_qid":null,"domain_hint":"Pharmacology","stem":"Option A Is correct\nTirofiban and abciximab are glycoprotein IIb/Illa\ninhibitors. Their mechanism of action is preventing\nfibrin from binding to platelets by occupying the\nglycoprotein Illa/IIb receptors. They may be\nindicated in management of unstable angina, or\nNSTEMI, particularly if early cardiac catheterization\nis planned.\nContraindications to their use include:\ne History of stroke within 30 days or any\nhistory of hemorrhagic stroke\ne Known history of intracranial disease (e.g.,\nneoplasm, arteriovenous malformation,\naneurysm)\ne Active or recent (within the previous 30\ndays) clinically relevant bleeding (e.g.,\ngastrointestinal bleeding)\ne Malignant hypertension\ne Trauma or major surgical intervention within\nthe past 6 weeks\ne Thrombocytopenia (platelet count\n<100,000/mm?","options":{"A":"disorders of platelet