INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('dd6230f5a1ae5158718d','AMEDEX 2025 Pharmacology 1-33.pdf','78','Pharmacology','A 60-year-old woman is prescribed sertraline
for management of depression. Her medical
history includes hypertension that is well-
controlled on nifedipine and atenolol. On
review after 2 months, she feels better but
her signs and symptoms of depression have
not resolved completely; therefore, the dose
of sertraline is increased. After 10 days, she
presents again complaining of palpitations.
On examination, she has a blood pressure of
100/78mmHg and heart rate of 110bpm. The
rest of the examination is inconclusive. Which
one of the following is most likely to have led
