INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('60064c74cb66d90f18c2','AMEDEX 2025 Pharmacology 1-33.pdf','96','Pharmacology','A 61-year-old man is brought to your clinic by
his wife with complaint of sudden-onset
tongue swelling. He is diabetic and is on
treatment with metformin and
chlorpropramide, has hypercholesterolemia
for which he takes simvastatin, and also
suffers from hypertension that is controlled
with ramipril. Four weeks ago, he presented
to his GP with complaints of fever and
productive cough, diagnosed as acute
bronchitis, and was prescribed amoxicillin.
On examination, his tongue is swollen. He
has difficulty speaking and points to his
tongue as the cause of his inability to speak.
On lung auscultation, wheezes are heard. No
rash is noted. Which one of the following
drugs can be the cause of this presentation?','{"A":"Metformin.","B":"Simvastatin.","C":"Amoxicillin.","D":"Ramipril.","E":"Chlorpropamide."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","supporting_pages":[96],"source_qid":null,"duplicate_group_id":"exact-7aaa11259164","duplicate_sources":[{"record_id":"60064c74cb66d90f18c2","record_type":"text_mcq","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_page":96,"source_qid":null},{"record_id":"3104e6fe377b5be41938","record_type":"text_mcq","source_file":"Amedex Pharma Onco Immuno 2025.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex Pharma Onco Immuno 2025.pdf","source_page":109,"source_qid":null},{"record_id":"314ebc8dce974e8bfd47","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1417,"source_qid":"967"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_same_page_five_structural","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"60064c74cb66d90f18c2","source_file":"AMEDEX 2025 Pharmacology 1-33.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Pharmacology 1-33.pdf","source_year":2025,"source_page":96,"supporting_pages":[96],"source_qid":null,"domain_hint":"Pharmacology","stem":"A 61-year-old man is brought to your clinic by\nhis wife with complaint of sudden-onset\ntongue swelling. He is diabetic and is on\ntreatment with metformin and\nchlorpropramide, has hypercholesterolemia\nfor which he takes simvastatin, and also\nsuffers from hypertension that is controlled\nwith ramipril. Four weeks ago, he presented\nto his GP with complaints of fever and\nproductive cough, diagnosed as acute\nbronchitis, and was prescribed amoxicill