INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7f4492d3d55e453686e4','AMEDEX 2025 Pharmacology 1-33.pdf','109','Pharmacology','A 54-year-old man presents to your GP clinic
with complaints of light-headedness and
palpitation for 3 days. He is hypertensive and
has been on nifedipine and
hydrochlorothiazide for the past 5 years.
Recently, he was diagnosed with generalized
anxiety disorder and started on fluoxetine.
On examination, he has a blood pressure of
90/60 mmHg, heart rate of 110 bpm,
respiratory rate of 14 breaths per minute,
and temperature of 37.5°C. The rest of the
exam is inconclusive. An EGG is obtained,
which shows sinus tachycardia with no other
